import ast, json, os, re, sys

ROOT = sys.argv[1] if len(sys.argv) > 1 else "."
SERVICES = os.path.join(ROOT, "services")
LFS_FIRST = "version https://git-lfs.github.com/spec/v1"

def read(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()

def is_pointer(path):
    try:
        with open(path, "rb") as f:
            first = f.readline().rstrip(b"\r\n")
        return first.decode("utf-8", "replace") == LFS_FIRST
    except Exception:
        return False

def py_files(src):
    out = []
    for base, dirs, files in os.walk(src):
        dirs[:] = [d for d in dirs if d != "__pycache__"]
        for fn in files:
            if fn.endswith(".py"):
                out.append(os.path.join(base, fn))
    return sorted(out)

def c1(cfg):
    return not (cfg.get("exposure") == "public" and cfg.get("timeout_s", 10**9) > 30)

def c2(handlers_src):
    tree = ast.parse(handlers_src)
    bad = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("handle_"):
            if ast.get_docstring(node) is None:
                bad.append(node.name)
    return not bad, bad

def c3(files):
    bad = []
    for p in files:
        try:
            tree = ast.parse(read(p))
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "print":
                bad.append(f"{p}:{node.lineno}")
    return not bad, bad

def c5(df):
    bad = []
    for line in df.splitlines():
        m = re.match(r"^\s*FROM\s+(.*)$", line, re.IGNORECASE)
        if not m:
            continue
        toks = [t for t in m.group(1).split() if not t.startswith("--")]
        if not toks or not re.search(r"@sha256:[0-9a-f]{64}$", toks[0]):
            bad.append(line.strip())
    return not bad, bad

def c6(df):
    users = [l.strip() for l in df.splitlines() if re.match(r"^\s*USER\s+", l, re.IGNORECASE)]
    if not users:
        return False, ["no USER"]
    user = users[-1].split(None, 1)[1].strip().split(":")[0]
    return user not in ("root", "0"), [users[-1]]

def c7(readme):
    return bool(re.search(r"(?m)^## Runbook$", readme))

def c8(codeowners, team):
    for line in codeowners.splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0] == "*":
            if "@team-" + team in parts[1:]:
