import ast, io, json, os, re, tokenize

def toks(path):
    with open(path,'rb') as f:
        return list(tokenize.tokenize(f.readline))

def check(svc):
    b=f'services/{svc}'
    cfg=json.load(open(f'{b}/config.json'))
    bad=set()
    pub=cfg.get('exposure')=='public'
    if pub and not (cfg.get('timeout_s') is not None and cfg['timeout_s']<=30): bad.add('C1')
    # C2 via ast
    hp=f'{b}/src/handlers.py'
    fr=open(hp,'rb').readline()
    if not fr.startswith(b'version https://git-lfs'):
        tree=ast.parse(open(hp).read())
        for n in ast.walk(tree):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith('handle_'):
                if not n.body or not (isinstance(n.body[0],ast.Expr) and isinstance(n.body[0].value,ast.Constant) and isinstance(n.body[0].value.value,str)):
                    bad.add('C2')
    # C3 via tokenize: NAME print followed by OP ( and previous significant token not '.'
    for base,dirs,files in os.walk(f'{b}/src'):
        for fn in files:
            if not fn.endswith('.py'): continue
            p=os.path.join(base,fn)
            if open(p,'rb').readline().startswith(b'version https://git-lfs'): continue
            ts=[t for t in toks(p) if t.type not in (tokenize.NL,tokenize.NEWLINE,tokenize.INDENT,tokenize.DEDENT,tokenize.ENCODING,tokenize.COMMENT)]
            for i,t in enumerate(ts):
                if t.type==tokenize.NAME and t.string=='print' and i+1<len(ts) and ts[i+1].string=='(':
                    if i==0 or ts[i-1].string != '.':
                        bad.add('C3')
    r=cfg.get('retries')
    if not (type(r) is int and 1<=r<=5): bad.add('C4')
    df=open(f'{b}/Dockerfile').read()
    for line in df.splitlines():
        if re.match(r'(?i)^\s*FROM\b',line):
            rest=re.sub(r'(?i)^\s*FROM\s+','',line)
            image=rest.split()[0]
            m=re.search(r'@sha256:([0-9a-f]+)$',image)
            if not m or len(m.group(1))!=64: bad.add('C5')
    users=[l.strip() for l in df.splitlines() if re.match(r'(?i)^\s*USER\s+',l)]
    if not users: bad.add('C6')
    else:
        u=users[-1].split(None,1)[1].split(':')[0].strip()
        if u in ('root','0'): bad.add('C6')
    if '## Runbook' not in open(f'{b}/README.md').read().splitlines(): bad.add('C7')
    team=cfg.get('team')
    okc8=False
    for line in open(f'{b}/CODEOWNERS'):
        s=line.strip()
        if s and not s.startswith('#') and s.split()[0]=='*' and f'@team-{team}' in s.split()[1:]:
            okc8=True
    if not okc8: bad.add('C8')
    # C9 via tokenize strings
    for base,dirs,files in os.walk(f'{b}/src'):
        for fn in files:
            if not fn.endswith('.py'): continue
            p=os.path.join(base,fn)
            if open(p,'rb').readline().startswith(b'version https://git-lfs'): continue
            for t in toks(p):
                if t.type==tokenize.STRING:
                    s=t.string
                    try:
                        val=ast.literal_eval(s)
                    except Exception:
                        continue
                    if isinstance(val,str) and (val.startswith('sk_live_') or val.startswith('AKIA')):
                        bad.add('C9')
    hc=cfg.get('healthcheck')
    if not hc: bad.add('C10')
    else:
        want='handle_'+str(hc).rstrip('/').split('/')[-1]
        names=set()
        if not fr.startswith(b'version https://git-lfs'):
            names={n.name for n in ast.walk(ast.parse(open(hp).read())) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
        if want not in names: bad.add('C10')
    if cfg.get('metrics_port')==cfg.get('port'): bad.add('C11')
    for line in open(f'{b}/requirements.txt').read().splitlines():
        s=line.strip()
        if s and not s.startswith('#'):
            if not re.fullmatch(r'[^=\s]+==[^=\s]+',s): bad.add('C12')
    if cfg.get('log_level')=='DEBUG': bad.add('C13')
    if pub and cfg.get('max_body_kb') is not None and cfg['max_body_kb']>1024: bad.add('C14')
    if not any(re.fullmatch(r'test_.*\.py',n) and os.path.isfile(os.path.join(f'{b}/tests',n)) for n in os.listdir(f'{b}/tests')): bad.add('C15')
    if pub:
        v=cfg.get('rate_limit_rps')
        if not (type(v) is int and 1<=v<=10000): bad.add('C16')
    return sorted(bad, key=lambda x:int(x[1:]))

for svc in sorted(os.listdir('services')):
    b=f'services/{svc}'
    ptr=[]
    for base,dirs,files in os.walk(b):
        for fn in files:
            p=os.path.join(base,fn)
            if open(p,'rb').readline().rstrip(b'\r\n')==b'version https://git-lfs.github.com/spec/v1': ptr.append(p)
    if ptr:
        status='unverifiable'; v=[]
    else:
        v=check(svc); status='violations' if v else 'compliant'
    expect=json.load(open(f'findings/{svc}.json'))
    got={'service':svc,'status':status,'violations':v}
    if got!=expect: print('MISMATCH',svc,got,expect)
print('comparison done')
